'use strict';
function squadValue(p,key){return key==='note'?roleNote(p):key==='potential'?potentialAtRole(p):key==='minutes'?p.dev.minutes:key==='physical'?physicalLoadValue(p):key==='contract'?p.contractEnd:p[key]}
function sortSquad(key){if(!['name','age','note','condition','potential','salary','contract','minutes','physical'].includes(key))return;if(squadSort===key)squadDescending=!squadDescending;else{squadSort=key;squadDescending=key!=='name'}render()}
function squadRows(){return club().players.filter(p=>squadFamily==='all'||slotEligible(p,Number(squadFamily))).sort((a,b)=>{const x=squadValue(a,squadSort),y=squadValue(b,squadSort),n=typeof x==='string'?x.localeCompare(y,'fr'):x-y;return(squadDescending?-n:n)||a.name.localeCompare(b.name,'fr')})}
function toggleCompare(id){if(!player(id))return;if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else compareIds=[...compareIds.slice(-1),id];render()}
function filterSquadText(value){const q=value.toLocaleLowerCase('fr');document.querySelectorAll('[data-squad-name]').forEach(row=>row.hidden=!row.dataset.squadName.includes(q))}
function comparePanel(){const players=compareIds.map(player).filter(Boolean);if(!players.length)return '';return `<section class="card comparison-panel" aria-label="Comparaison de joueurs"><div class="cardtitle"><h2>Comparer les profils</h2><button class="small" onclick="compareIds=[];render()">Effacer la comparaison</button></div>${players.length===1?'<p>Sélectionnez un second joueur dans le tableau pour comparer leurs qualités.</p>':''}${players.length===2&&players[0].fam!==players[1].fam?'<p class="notice">Postes différents : comparez les qualités utiles à chaque rôle, plutôt que les seules notes générales.</p>':''}<div class="tablewrap"><table><thead><tr><th>QUALITÉ</th>${players.map(p=>`<th>${p.name}<small>${p.pos}</small></th>`).join('')}</tr></thead><tbody>${[['Âge',p=>p.age],['Note au poste',roleNote],['Condition',p=>Math.round(p.condition)+'%'],['Charge cumulée',p=>physicalLoadValue(p)+'/100'],['Potentiel au poste',potentialAtRole],['Salaire / semaine',p=>money(p.salary)],...Object.entries(ATTR).map(([key,label])=>[label,p=>Math.round(skill(p,key))])].map(([label,value])=>`<tr><td>${label}</td>${players.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function squadTable(){return `<div class="stack">${comparePanel()}<section class="card"><div class="cardtitle"><h2>L’effectif professionnel</h2><span class="tag">${club().players.length} JOUEURS</span></div><div class="squad-toolbar"><label>Poste<select aria-label="Filtrer par poste" onchange="squadFamily=this.value;render()"><option value="all">Tous les postes</option>${POS.map((p,i)=>`<option value="${i}" ${squadFamily===String(i)?'selected':''}>${i+1} · ${p}</option>`).join('')}</select></label><label>Rechercher<input type="search" placeholder="Nom ou poste" aria-label="Rechercher dans l’effectif" oninput="filterSquadText(this.value)"></label><span class="help">Cliquez sur un titre pour trier. Comparez deux joueurs.</span></div><div class="tablewrap"><table class="manager-squad-table"><thead><tr><th>COMPARER</th>${[['name','JOUEUR'],['age','ÂGE'],['note','NOTE AU POSTE'],['condition','CONDITION'],['potential','POTENTIEL'],['salary','SALAIRE'],['contract','FIN CONTRAT'],['minutes','MINUTES'],['physical','CHARGE']].map(([key,label])=>`<th><button class="sort-button" aria-label="Trier par ${label.toLowerCase()}" onclick="sortSquad('${key}')">${label} ${squadSort===key?(squadDescending?'↓':'↑'):''}</button></th>`).join('')}<th>PLAN</th><th>STATUT</th></tr></thead><tbody>${squadRows().map(p=>`<tr data-squad-name="${visualEscape((p.name+' '+p.pos).toLocaleLowerCase('fr'))}"><td><button class="small ${compareIds.includes(p.id)?'dark':''}" aria-pressed="${compareIds.includes(p.id)}" aria-label="Comparer ${p.name}" onclick="toggleCompare('${p.id}')">${compareIds.includes(p.id)?'✓':'+'}</button></td><td><button class="textbutton" onclick="inspectPlayer('${p.id}')">${p.name}</button><small>${p.pos}</small><small>Objectif : ${developmentFocusValue(p)==='equilibre'?'Équilibré':ATTR[developmentFocusValue(p)]}</small></td><td>${p.age}</td><td><span class="rating">${roleNote(p)}</span></td><td>${Math.round(p.condition)}%</td><td>${potentialAtRole(p)}</td><td>${money(p.salary)}</td><td>S${p.contractEnd}${p.contractEnd===S.season?' · À prolonger':''}</td><td>${Math.round(p.dev.minutes)}</td><td>${physicalLoadValue(p)}/100</td><td class="physical-plan"><select aria-label="Charge de ${visualEscape(p.name)}" onchange="setPhysicalTraining('${p.id}',this.value)" ${S.live||S.trained||S.phase==='ended'?'disabled':''}>${Object.entries(PHYSICAL_PLANS).map(([mode,label])=>'<option value="'+mode+'"'+(physicalPlan(p)===mode?' selected':'')+'>'+label+'</option>').join('')}</select><small>${physicalLoadPreviewText(p)}</small></td><td>${p.injury?'Blessé · '+p.injury+' sem.':S.lineup.includes(p.id)?'Titulaire':S.reserves.includes(p.id)?'Banc':'Hors groupe'}</td></tr>`).join('')}</tbody></table></div></section></div>`}
// Consultation tactique locale : ni mutation du moteur ni persistance de sauvegarde.
let squadDepthAlertsOnly=false;
function squadDepthReadiness(p){
 const condition=Number(p.condition),load=Number(physicalLoadValue(p));
 if(p.injury)return {ready:false,reason:'Blessé'};
 if(!Number.isFinite(condition)||!Number.isFinite(load))return {ready:false,reason:'État physique inconnu'};
 if(condition<70)return {ready:false,reason:'Condition faible'};
 if(load>=70)return {ready:false,reason:'Charge élevée'};
 return {ready:true,reason:'Prêt'};
}
function depthAt(slot){return club().players.filter(p=>slotEligible(p,slot)).sort((a,b)=>Number(!!a.injury)-Number(!!b.injury)||fitScore(b,FAMILIES[slot])-fitScore(a,FAMILIES[slot]))}
function squadDepth(){
 const cards=POS.map((label,slot)=>{
  const choices=depthAt(slot),fit=choices.filter(p=>!p.injury),ready=choices.filter(p=>squadDepthReadiness(p).ready);
  const alert=ready.length<2,missing=Math.max(0,2-ready.length);
  return {label,slot,choices,fit,ready,alert,missing};
 });
 const alerts=cards.filter(c=>c.alert),shown=squadDepthAlertsOnly?alerts:cards;
 return `<div class="stack"><section class="card"><div class="cardtitle"><h2>Préparer la rotation</h2><span class="tag">${alerts.length} POSTE(S) À RISQUE</span></div><p class="help">Un joueur est considéré prêt pour la rotation s'il n'est pas blessé, possède au moins 70 % de condition et une charge inférieure à 70/100. Indicateur d'aide à la décision, pas une interdiction de sélection.</p><button type="button" class="small ${squadDepthAlertsOnly?'dark':''}" aria-pressed="${squadDepthAlertsOnly}" onclick="squadDepthAlertsOnly=!squadDepthAlertsOnly;render()">${squadDepthAlertsOnly?'Afficher tous les postes':'Voir uniquement les postes à risque'}</button><button type="button" class="small" onclick="squadTab='sheet';render()">Préparer les 23 →</button></section><div class="depth-grid">${shown.map(c=>`<section class="card depth-card ${c.alert?'thin-depth':''}"><div class="cardtitle"><h2>${c.slot+1} · ${c.label}</h2><span class="tag">${c.ready.length} PRÊTS / ${c.fit.length} APTES</span></div>${c.choices.slice(0,4).map((p,i)=>{const state=squadDepthReadiness(p);return `<button class="depth-player" onclick="inspectPlayer('${p.id}')"><b>${i+1}</b><span>${p.name}<small>${state.reason} · ${Math.round(Number(p.condition)||0)}% de condition · charge ${physicalLoadValue(p)}/100</small></span><strong>${roleNote(p,FAMILIES[c.slot])}</strong></button>`}).join('')||'<p>Aucun joueur éligible.</p>'}${c.alert?`<p class="help danger">Rotation fragile : ${c.missing} joueur(s) prêt(s) manquant(s) pour couvrir ce poste à deux.</p>`:'<p class="help">Rotation couverte par au moins deux joueurs prêts.</p>'}</section>`).join('')||'<p class="help">Aucun poste à risque selon les seuils actuels.</p>'}</div></div>`;
}
function managerTeamView(){const tabs=`<div class="tabs squad-tabs">${[['table','Tableau de l’effectif'],['depth','Couverture des postes'],['planning','Plan sur 3 saisons'],['health','Disponibilité & rotation'],['sheet','Feuille à 23']].map(([key,title])=>`<button class="${squadTab===key?'dark':''}" onclick="squadTab='${key}';render()">${title}</button>`).join('')}</div>`;if(typeof ui02TeamView==='function'&&typeof CDUI02Data==='object'&&typeof CDUI02Components==='object'&&squadTab==='profile')return ui02TeamView();if(typeof ui02TeamView==='function'&&typeof CDUI02Data==='object'&&typeof CDUI02Components==='object'&&squadTab==='table')return tabs+ui02TeamView();if(squadTab==='sheet')return tabs+rugbyTeam();if(squadTab==='health'&&typeof squadHealthView==='function')return tabs+squadHealthView();return heading('LES HOMMES DU PROJET','Construire votre effectif.','Comparez les profils, anticipez les contrats et vérifiez la couverture des postes.',`<button class="primary" onclick="squadTab='sheet';render()">Composer les 23 →</button>`)+tabs+(squadTab==='depth'?squadDepth():squadTab==='planning'?successionPlanningPanel():squadTable())}
